            a[1] += krw;
        }
        List<DailyLine> out = new ArrayList<>();
        for (var e : acc.entrySet()) {
            String[] k = e.getKey().split("\\|");
            Partner p = data.partner(k[1]).orElseThrow();
            long gross = e.getValue()[1];
            out.add(new DailyLine(LocalDate.parse(k[0]), p.id(), (int) e.getValue()[0], gross,
                    Money.fee(gross, p.feeBps())));
        }
        return out;
    }

    /**
     * Settled transactions of one active partner in the KST date range, in date then approval order.
     * Same amounts as {@link #settle}; used for the partner-facing detail statement.
     */
    public List<SettledTxn> transactions(String partnerId, LocalDate from, LocalDate to) {
        List<SettledTxn> out = new ArrayList<>();
        Partner p = data.partner(partnerId).orElse(null);
        if (p == null || !p.active()) return out;
        for (Transaction t : data.transactions()) {
            if (!t.partnerId().equals(p.id())) continue;
            LocalDate d = dates.dateOf(t.approvedAt());
            if (d.isBefore(from) || d.isAfter(to)) continue;
            out.add(settled(t, d));
        }
        out.sort(Comparator.comparing(SettledTxn::date).thenComparing(s -> s.txn().approvedAt()));
        return out;
    }

    /**
     * One transaction as settled. publicRate is null when the applied rate is a B-2 (non-public)
     * source value, which must not appear in anything sent outside the company.
     */
    public record SettledTxn(LocalDate date, Transaction txn, BigDecimal publicRate, long krwAmount) {}

    private SettledTxn settled(Transaction t, LocalDate businessDate) {
        RateService.AppliedRate r = rates.settlementRate(t.currency(), businessDate);
        long krw = Money.toKrw(t.signedAmount(), r.rate(), CurrencyPairs.unitOf(t.currency()));
        return new SettledTxn(businessDate, t, r.publicSource() ? r.rate() : null, krw);
    }
}

